// Cached CatmullRom splines for each floor to ensure continuous smooth traversal
const splineCache = new Map<string, THREE.CatmullRomCurve3>();

export function getSplineForFloor(floorSlug: string): THREE.CatmullRomCurve3 {
  const normalized = floorSlug === "underground-floor" ? "underground" : floorSlug;
  if (splineCache.has(normalized)) {
    return splineCache.get(normalized)!;
  }

  const pathData = architecturalCameraPaths[normalized] || architecturalCameraPaths["ground-floor"];
  const vectors = pathData.positions.map((p) => new THREE.Vector3(p[0], p[1], p[2]));
  // Centripetal Catmull-Rom curve with tension 0.5 avoids overshoot around tight corners
  const spline = new THREE.CatmullRomCurve3(vectors, false, "catmullrom", 0.5);
  splineCache.set(normalized, spline);
  return spline;
}

