const _parallaxQuat = new THREE.Quaternion();

/**
 * Evaluates the precise 3D position and orientation at any progress (0.0 to 1.0)
 * along the authentic architectural layout without clipping through walls.
 */
export function evaluateCameraTransform(
  floorSlug: string,
  progress: number,
  outPosition: THREE.Vector3,
  outQuaternion: THREE.Quaternion,
  mouseOffset?: { x: number; y: number }
): void {
  const normalized = floorSlug === "underground-floor" ? "underground" : floorSlug;
  const pathData = architecturalCameraPaths[normalized] || architecturalCameraPaths["ground-floor"];
  const clampedProgress = Math.max(0, Math.min(1, progress));

  // 1. Continuous Position along Catmull-Rom architectural corridor spline
  const spline = getSplineForFloor(normalized);
  spline.getPointAt(clampedProgress, outPosition);

  // 2. Continuous Spherical Linear Interpolation (Slerp) between rotation keyframes
  const n = pathData.rotations.length;
  const u = clampedProgress * (n - 1);
  const idx = Math.min(n - 2, Math.max(0, Math.floor(u)));
  const frac = u - idx;

  const rotA = pathData.rotations[idx];
  const rotB = pathData.rotations[idx + 1];

  _tempQuatA.set(rotA[0], rotA[1], rotA[2], rotA[3]);
  _tempQuatB.set(rotB[0], rotB[1], rotB[2], rotB[3]);
  outQuaternion.copy(_tempQuatA).slerp(_tempQuatB, frac);

  // 3. Subtle organic mouse parallax (without shifting camera through walls)
  if (mouseOffset && (mouseOffset.x !== 0 || mouseOffset.y !== 0)) {
    _parallaxEuler.set(
      -mouseOffset.y * 0.12,
      -mouseOffset.x * 0.18,
      0,
      "YXZ"
    );
    _parallaxQuat.setFromEuler(_parallaxEuler);
    outQuaternion.multiply(_parallaxQuat);
  }
}
